import 'bundled_track.dart';

/// One item in the built-in royalty-free library (`audio_library.dart`,
/// generated by `tools/make_audio_library.py`): a music track or a sound
/// effect. All of it is original, synthesised in that script — CC0.
class LibrarySound {
  final String id;
  final String title;
  final String category;
  final String mood;

  /// Tempo for music (used by AutoCut to cut on the beat), 0 for effects.
  /// Every library track starts exactly on a beat.
  final int bpm;
  final int durationMs;
  final bool isSfx;
  final String assetPath;

  const LibrarySound({
    required this.id,
    required this.title,
    required this.category,
    required this.mood,
    required this.bpm,
    required this.durationMs,
    required this.isSfx,
    required this.assetPath,
  });

  /// For `AudioImportService.pickFromLibrary`, which copies the asset into
  /// app storage as `bundled_audio/<id>.m4a`.
  BundledTrack get asTrack => BundledTrack(id: id, title: title, assetPath: assetPath, durationMs: durationMs);
}
